static boolean isValid(String text) {
        if (text == null || text.length() == 0) {
            return false;
        }
        if(!text.startsWith("{") & !text.startsWith("[")){
            return false;
        }
        JSONReader jsonReader = JSONReader.of(text);
        try {
            jsonReader.skipValue();
        } catch (JSONException error) {
            return false;
        }
        return true;
    }

