package com.alibaba.fastjson2;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class JSONIsValidTest {

    @Test
    public void testIsValid() {
        // Test cases for JSON.isValid()
        // Valid JSON object
        assertTrue(JSON.isValid("{}"));
        assertTrue(JSON.isValid("{\"key\":\"value\"}"));
        // Valid JSON array
        assertTrue(JSON.isValid("[]"));
        assertTrue(JSON.isValid("[1,2,3]"));
        // Invalid cases that should return false
        assertFalse(JSON.isValid((String) null));
        assertFalse(JSON.isValid(""));
        // New condition: text must start with '{' or '['
        assertFalse(JSON.isValid("invalid"));
        assertFalse(JSON.isValid("123"));
        assertFalse(JSON.isValid("\"string\""));
        assertFalse(JSON.isValid("true"));
        assertFalse(JSON.isValid("false"));
        assertFalse(JSON.isValid("null"));
